-- ============================================================
-- Migration 057 — Atölye gider beyanı, 2026-09 (ayrı kayıt)
-- ============================================================
--
-- Kaynak: "Atolye_Performans_Kiyas_Asgari_Ucret_Analizi.xlsx" › VERİLER
--   (kökeni "Atölye Gider Bilgileri-FORM 1 (2).xlsx", 20 atölye beyanı).
--
-- NEDEN 2026-09: İlk 11 atölyenin 2026-08 kaydı aynı formun önceki
--   sürümünden (9 Eylül) aktarılmıştı ve bazı kalemleri farklı. Hakan'ın
--   kararı (2026-11-17): eski kayıtlara DOKUNULMAZ, bu veri 2026-09
--   dönemine ayrı kayıt olarak yazılır; ikisi yan yana durur.
--
-- Eşleştirme (Excel adı → workshop.code), elle doğrulandı:
--   HEDİYE GROUP→B024 · NETCLASS→B063 (NETCLAS) · SRTTEKS→B089 · SİMAYTEKS→B026
--   DEMA→B017 (MEM TEX / DEMA) · KARTAL FASHION→B056 (KARTAL TEKSTİL, pasif;
--   Hakan: aynı firma) · KARATUR→B115, AYAZ EFE→B116 (listede yoktu, YENİ atölye)
--
-- Kalem eşlemesi: UKP sarf→ukp_consumables, kırtasiye→stationery, diğer
--   amortisman→vehicle_depr (037 kolonları); "Diğer giderler"→communication
--   (formdaki soru "Telefon, internet"). Değerler beyan edildiği gibi yazılır;
--   şüpheliler düzeltilmedi: TOPRAK ek resmî gider 4.250.000, AYAZ EFE fazla
--   mesai 2.500.000, DEMA maaş 4.200.000 (kaynakta 420.000 ile çelişiyor).
--
-- Ham satır expense_declaration_staging.raw'da saklanır (izlenebilirlik).
-- Tekrar çalıştırılabilir: 2026-09 kaydı olan atölye atlanır.
--
-- ROLLBACK:
--   DELETE FROM monthly_expense WHERE year = 2026 AND month = 9;
--   DELETE FROM expense_declaration_staging WHERE donem = '2026-09';
--   DELETE FROM workshop WHERE code IN ('B115','B116');
-- ============================================================

BEGIN;

-- 1. Listede olmayan iki atölye (kadro Excel'deki beyandan; bölge bilinmiyor → varsayılan)
INSERT INTO workshop (tenant_id, code, name, type, production_type,
                      total_staff, sewing_staff, ukp_staff, cutting_staff, management, net_hours_day)
SELECT (SELECT tenant_id FROM workshop WHERE code = 'B013'), v.*
FROM (VALUES
    ('B115', 'KARATUR', 'X', 'CMT', 106, 58, 35, 6, 7, 9),
    ('B116', 'AYAZ EFE', 'X', 'CMT', 75, 40, 25, 5, 5, 9)
) AS v(code, name, type, production_type, total_staff, sewing_staff, ukp_staff, cutting_staff, management, net_hours_day)
ON CONFLICT (code) DO NOTHING;

