st AS (
    INSERT INTO expense_declaration_staging
        (tenant_id, source, source_ref, donem, raw, workshop_id, match_status,
         promoted_at, revision_no, revision_note)
    SELECT w.tenant_id, 'forms_xlsx', 'Atolye_Performans_Kiyas_Asgari_Ucret_Analizi.xlsx',
           '2026-09', v.raw, w.id, 'matched', NOW(), 1,
           'Atölye gider formu (FORM 1 (2)) — 2026-08 kaydından ayrı tutuldu'
    FROM v JOIN workshop w ON w.code = v.code
    WHERE NOT EXISTS (SELECT 1 FROM monthly_expense me
                      WHERE me.workshop_id = w.id AND me.year = 2026 AND me.month = 9)
    RETURNING id, workshop_id, tenant_id
)
INSERT INTO monthly_expense
    (workshop_id, tenant_id, year, month, work_days, current_staging_id, revision_no,
     personnel, overtime, bonus, sgk, food, transport, cargo, rent, electricity, water, gas, thread, ukp_consumables, consumables, machine_maint, stationery, isg, consulting, official_fees, insurance, communication, vehicle, incentive_amount, building_depr, machine_depr, vehicle_depr, severance_reserve)
SELECT st.workshop_id, st.tenant_id, 2026, 9, v.work_days, st.id, 1,
       v.personnel, v.overtime, v.bonus, v.sgk, v.food, v.transport, v.cargo, v.rent, v.electricity, v.water, v.gas, v.thread, v.ukp_consumables, v.consumables, v.machine_maint, v.stationery, v.isg, v.consulting, v.official_fees, v.insurance, v.communication, v.vehicle, v.incentive_amount, v.building_depr, v.machine_depr, v.vehicle_depr, v.severance_reserve
FROM st
JOIN workshop w ON w.id = st.workshop_id
JOIN v ON v.code = w.code;

-- Güvence: 20 atölyenin tamamı yazılmış olmalı (eşleşmeyen kod sessizce düşmesin)
DO $$
DECLARE n INT;
BEGIN
    SELECT count(*) INTO n FROM monthly_expense
    WHERE year = 2026 AND month = 9 AND current_staging_id IS NOT NULL;
    IF n <> 20 THEN
        RAISE EXCEPTION '2026-09 gider kaydı % adet, 20 bekleniyordu', n;
    END IF;
END $$;

COMMIT;
